WITH scored AS (SELECT id, order_id, product_id, RANK() OVER (PARTITION BY product_id, order_id ORDER BY quantity DESC) AS quantity_rank, LEAD(quantity, 1) OVER (ORDER BY unit_price ASC, id ASC) AS next_quantity FROM order_items) SELECT CASE WHEN next_quantity >= 7 THEN 'HIGH' ELSE 'LOW' END AS next_quantity_tier, CASE WHEN quantity_rank >= 7 THEN 'LARGE' ELSE 'SMALL' END AS quantity_rank_tier, APPROX_PERCENTILE(quantity_rank, 0.95) AS quantity_rank_p95, COUNT(*) AS cnt, ROUND(AVG(quantity_rank), 2) AS avg_quantity_rank, RANK() OVER (PARTITION BY CASE WHEN next_quantity >= 7 THEN 'HIGH' ELSE 'LOW' END ORDER BY ROUND(AVG(quantity_rank), 2) DESC) AS avg_quantity_rank_rank FROM scored GROUP BY CASE WHEN next_quantity >= 7 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN quantity_rank >= 7 THEN 'LARGE' ELSE 'SMALL' END
